const supabase = require('../../config/db.config');

const TABLE = 'turfs';

const findTurfsByOwnerId = async (ownerId) => {
  const { data, error } = await supabase
    .from(TABLE)
    .select('*')
    .eq('owner_id', ownerId)
    .is('deleted_at', null)
    .order('created_at', { ascending: false });

  if (error) throw error;
  return data || [];
};

const findTurfById = async (id) => {
  const { data, error } = await supabase
    .from(TABLE)
    .select('*')
    .eq('id', id)
    .is('deleted_at', null)
    .single();

  if (error && error.code !== 'PGRST116') throw error;
  return data || null;
};

const findAllTurfs = async () => {
  const { data, error } = await supabase
    .from(TABLE)
    .select('*')
    .is('deleted_at', null)
    .order('created_at', { ascending: false });

  if (error) throw error;
  return data || [];
};

const createTurf = async (data) => {
  const { data: turf, error } = await supabase
    .from(TABLE)
    .insert(data)
    .select()
    .single();

  if (error) throw error;
  return turf;
};

const updateTurf = async (id, data) => {
  const { data: turf, error } = await supabase
    .from(TABLE)
    .update({ ...data, updated_at: new Date().toISOString() })
    .eq('id', id)
    .select()
    .single();

  if (error) throw error;
  return turf;
};

const deleteTurf = async (id) => {
  const { data: turf, error } = await supabase
    .from(TABLE)
    .update({ deleted_at: new Date().toISOString() })
    .eq('id', id)
    .select()
    .single();

  if (error) throw error;
  return turf;
};

module.exports = {
  findTurfsByOwnerId,
  findTurfById,
  findAllTurfs,
  createTurf,
  updateTurf,
  deleteTurf,
};
```

